public class LongitudeDifference {
public static double longitudeDifference(double lonD1, double lonD2)
    {
        double delta = lonD1 - lonD2;
        if (delta < 0.)
        {
            delta *= -1.;
        }
        if (delta > 360.)
        {
            delta -= (int)(delta / 360.) * 360.;
        }
        if (delta > 180.)
        {
            delta = 360. - delta;
        }

        return delta;
    }
}

