        Assert.assertEquals(20., LatLonAlt.longitudeDifference(-370., 370.), 0.);
        Assert.assertEquals(15., LatLonAlt.longitudeDifference(-175., 170.), 0.);
        Assert.assertEquals(0., LatLonAlt.longitudeDifference(-180., 180.), 0.);
        Assert.assertEquals(0., LatLonAlt.longitudeDifference(-190., 170.), 0.);
    }

Function:
public class NormalizeLatitude {
public static double normalizeLatitude(double in)
    {
        final double limit1 = 270.;
        final double limit2 = 450.;
        final double limit3 = 540.;
        double out = in;
        if (out > 90.)
        {
            if (out > limit3)
            {
                out %= 360.;
                if (out > limit1)
                {
                    out = out - 360;
                }
                else if (out > 90.)
                {
                    out = 180. - out;
                }
            }
            else if (out > limit1)
            {
                if (out > limit2)
                {
                    out = limit3 - out;
                }
                else
                {
                    out = out - 360;
                }
            }
            else if (out > 90.)
            {
                out = 180. - out;
            }
        }
        else if (out < -90)
        {
            if (out < -limit3)
            {
                out %= 360.;
                if (out < -limit1)
                {
                    out = out + 360;
                }
                else if (out < -90)
                {
                    out = -180 - out;
                }
            }
            else if (out < -limit1)
            {
                if (out < -limit2)
                {
                    out = -limit3 - out;
                }
                else
                {
                    out = out + 360;
                }
            }
            else if (out < -90)
            {
                out = -180 - out;
            }
        }
        return out;
    }
}

