Function:
public class Wrap {
public static int wrap(int value, int min, int max)
    {
        int newValue = value;
        final int step = max - min;

        if (newValue >= max)
        {
            while (newValue >= max)
            {
                newValue -= step;
            }
        }
        else if (newValue < min)
        {
            while (newValue < min)
            {
                newValue += step;
            }
        }
        return newValue;
    }
}

Test Case:
@Test
    void testWrap()
    {
        assertEquals(0, UtilMath.wrap(360, 0, 360));
        assertEquals(359, UtilMath.wrap(-1, 0, 360));
        assertEquals(180, UtilMath.wrap(180, 0, 360));
    }

Function:
public class WrapDouble {
public static double wrapDouble(double value, double min, double max)
    {
        double newValue = value;
        final double step = max - min;

        if (Double.compare(newValue, max) >= 0)
        {
            while (Double.compare(newValue, max) >= 0)
            {
                newValue -= step;
            }
        }
        else if (newValue < min)
        {
            while (newValue < min)
            {
                newValue += step;
            }
        }
        return newValue;
    }
}

Test Case:
@Test
    void testWrapDouble()
    {
        assertEquals(0.0, UtilMath.wrapDouble(360.0, 0.0, 360.0));
        assertEquals(359.0, UtilMath.wrapDouble(-1.0, 0.0, 360.0));
        assertEquals(180.0, UtilMath.wrapDouble(180.0, 0.0, 360.0));
    }

Function:
public class GetSign {
public static int getSign(double value)
    {
        final int sign;
        if (value > 0)
        {
            sign = 1;
        }
        else if (value < 0)
        {
            sign = -1;
        }
        else
        {
            sign = 0;
        }
        return sign;
    }
}

Test Case:
@Test
    void testSign()
    {
        assertEquals(-1, UtilMath.getSign(-1.0));
        assertEquals(1, UtilMath.getSign(1.0));
        assertEquals(0, UtilMath.getSign(0));
    }

Function:
public class GetRound {
public static double getRound(double speed, double value)
    {
        if (speed < 0)
        {
            return Math.floor(value);
        }
        return Math.ceil(value);
    }
}

